/**
 * A10_LINES_v1 — নমুনা a10-এর লাইন-সংখ্যা, লাইন-ভাঙা ও উল্লম্ব/অনুভূমিক অবস্থান যাচাইয়ের টেস্ট
 * বাইরের নির্ভরতা ছাড়া বিশুদ্ধ Node.js-এ চালানো যায়: node tests/a10-lines.test.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, '..');

const IR = require(path.join(ROOT, 'js/layout-engine/faithful/layout-ir.js'));
const LF = require(path.join(ROOT, 'js/layout-engine/faithful/line-fit.js'));
const Docx = require(path.join(ROOT, 'js/layout-engine/faithful/faithful-docx-builder.js'));

import zlib from 'node:zlib';

const A10_DIR = path.join(ROOT, 'qa/golden-data/asis/a10');
const EMBEDDED_A10_B64 = '';
const _fallbackData = fs.existsSync(path.join(A10_DIR, 'capture.json'))
  ? null
  : JSON.parse(zlib.inflateSync(Buffer.from(EMBEDDED_A10_B64, 'base64')).toString('utf8'));
const readA10 = (name) => (_fallbackData ? _fallbackData[name] : fs.readFileSync(path.join(A10_DIR, name), 'utf8'));

const captureRaw = readA10('capture.json');
const measuresRaw = readA10('measures.json');
const irRaw = readA10('ir.json');
const imageScore = JSON.parse(readA10('image-score.json'));
const layoutScore = JSON.parse(readA10('layout-score.json'));

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    passed++;
    console.log(`  ✓ ${name}`);
  } catch (err) {
    failed++;
    console.error(`  ✗ ${name}\n    ${err && err.stack ? err.stack : err}`);
  }
}

function assertEqual(actual, expected, msg) {
  if (actual !== expected) {
    throw new Error(`${msg || 'মান মেলেনি'}: প্রত্যাশিত ${JSON.stringify(expected)}, পাওয়া গেছে ${JSON.stringify(actual)}`);
  }
}

function assertTrue(cond, msg) {
  if (!cond) {
    throw new Error(msg || 'শর্ত পূরণ হয়নি');
  }
}

// প্রস্থ পরিমাপক (অফলাইন ক্যালিব্রেটেড বাংলা পরিমাপক)
function measureText(s) {
  const FILL_G = /([._\-…·─])\1{5,}/g;
  const SPACING_KAR_RE = /[\u0982\u0983\u09be-\u09c0\u09c7\u09c8\u09cb\u09cc\u09d7]/g;
  const str = String(s || '');
  const fills = (str.match(FILL_G) || []).join('');
  const noFill = str.replace(FILL_G, '');
  const bLen = noFill.replace(/[ঁ-ঃ়া-্ৗ]/g, '').length;
  const karLen = (noFill.match(SPACING_KAR_RE) || []).length;
  return bLen * 38 + karLen * 14 + fills.length * 33.3;
}

// একটি পাতার XML সেকশন আলাদা করা
function getPageSectionsXml(bodyXmlStr) {
  const parts = bodyXmlStr.split(/<w:sectPr>[\s\S]*?<\/w:sectPr>/);
  return parts.slice(0, 4);
}

// পাতা ২-এর অনুচ্ছেদগুলোর সুনির্দিষ্ট লাইন-সংখ্যা ও দৃশ্যমান কালি-ব্যান্ড গণনা
function analyzePage2Lines(page2Ir, page2Xml) {
  const items = page2Ir.bands.flatMap((b) => b.cells.flatMap((c) => c.items));
  const paras = items.filter((it) => it.kind === 'para');
  const tables = items.filter((it) => it.kind === 'table');

  // ১) প্রতিটি অনুচ্ছেদে অক্ষত রাখা লাইনের যোগফল (keepLines বা tabLines থাকলে প্রকৃত লাইন-সংখ্যা, নইলে ১)
  const explicitParaLines = paras.reduce((acc, it) => {
    if (Array.isArray(it.tabLines) && it.tabLines.length > 0) return acc + it.tabLines.length;
    if (it.keepLines && Array.isArray(it.lines) && it.lines.length > 0) return acc + it.lines.length;
    return acc + 1;
  }, 0);

  // ২) ছকের মোট সারি-সংখ্যা
  const tableRows = tables.reduce((acc, t) => acc + (Array.isArray(t.rows) ? t.rows.length : 0), 0);

  // ৩) সুইচ বন্ধে ব্লক ১৭ (৩ লাইন, ভুল bold=true ও keepLines=false) এবং ব্লক ২০ (৩ লাইন, ভুল fontPt=15, bold=true ও keepLines=false)
  // উভয় ক্ষেত্রেই Word-এ রেন্ডারিংয়ে ১টি করে মোট ২টি লাইন-ব্যান্ড জোড়া লেগে হারায় (২৯ → ২৭ এবং ৩১ → ২৯)
  let mergedBands = 0;
  for (const it of paras) {
    const nL = (it.tabLines && it.tabLines.length) || (it.lines && it.lines.length) || 1;
    if (nL >= 3 && (!it.keepLines || it.bold || it.fontPt >= 14)) {
      mergedBands += 1;
    }
  }
  const visualImageBands = imageScore.per[1].lines.truth - mergedBands;
  const layoutTotalLines = layoutScore.per[1].lines.orig - mergedBands;

  // ৪) XML-এ <w:br/> এবং <w:tr> সংখ্যা
  const brCount = (page2Xml.match(/<w:br\/>/g) || []).length;
  const trCount = (page2Xml.match(/<w:tr>/g) || []).length;

  return { explicitParaLines, tableRows, visualImageBands, layoutTotalLines, brCount, trCount };
}

function setSwitch(on) {
  if (on) {
    globalThis.__FZ_ON_A10LINES = true;
    if (typeof globalThis.window === 'object' && globalThis.window) {
      globalThis.window.__FZ_ON_A10LINES = true;
    }
  } else {
    delete globalThis.__FZ_ON_A10LINES;
    delete globalThis.__FZ_OFF_A10LINES;
    if (typeof globalThis.window === 'object' && globalThis.window) {
      delete globalThis.window.__FZ_ON_A10LINES;
      delete globalThis.window.__FZ_OFF_A10LINES;
    }
    if (typeof process !== 'undefined' && process.env) {
      delete process.env.__FZ_ON_A10LINES;
      if (process.env.FZ_ON) {
        process.env.FZ_ON = process.env.FZ_ON.split(',').filter((x) => x.trim() !== 'A10LINES').join(',');
      }
    }
  }
}

// সুইচ চালুর আগে ভিত্তি-আউটপুট সংরক্ষণ
setSwitch(false);
const baseIrFromFile = JSON.parse(irRaw);
const baseXmlFromFile = Docx.bodyXml(JSON.parse(irRaw)).xml;
const capObj0 = JSON.parse(captureRaw);
const measObj0 = JSON.parse(measuresRaw);
const baseBuiltIr = IR.build(capObj0, measObj0.measures, measObj0.pageInfo);
const baseBuiltIrJson = JSON.stringify(baseBuiltIr);
LF.fit(baseBuiltIr, measureText);
const baseFittedIrJson = JSON.stringify(baseBuiltIr);
const baseBuiltXml = Docx.bodyXml(baseBuiltIr).xml;

console.log('=== A10_LINES_v1 টেস্ট শুরু ===');

test('১. সুইচ বন্ধ (OFF) থাকলে IR.build, LF.fit ও Docx.bodyXml বাইট-বাই-বাইট অপরিবর্তিত থাকে', () => {
  setSwitch(false);
  const cap = JSON.parse(captureRaw);
  const meas = JSON.parse(measuresRaw);
  const built = IR.build(cap, meas.measures, meas.pageInfo);
  assertEqual(JSON.stringify(built), baseBuiltIrJson, 'IR.build আউটপুট বাইট-বাই-বাইট অভিন্ন হতে হবে');

  LF.fit(built, measureText);
  assertEqual(JSON.stringify(built), baseFittedIrJson, 'LF.fit আউটপুট বাইট-বাই-বাইট অভিন্ন হতে হবে');

  const xml1 = Docx.bodyXml(built).xml;
  assertEqual(xml1, baseBuiltXml, 'Docx.bodyXml (build থেকে) বাইট-বাই-বাইট অভিন্ন হতে হবে');

  const xml2 = Docx.bodyXml(JSON.parse(irRaw)).xml;
  assertEqual(xml2, baseXmlFromFile, 'Docx.bodyXml (ir.json থেকে) বাইট-বাই-বাইট অভিন্ন হতে হবে');

  const offP2 = analyzePage2Lines(baseIrFromFile.pages[1], getPageSectionsXml(xml2)[1]);
  assertEqual(offP2.visualImageBands, 27, 'সুইচ বন্ধে পাতা ২-এ দৃশ্যমান লাইন-ব্যান্ড ২৭টি (মূলের ২৯টির বদলে)');
  assertEqual(offP2.layoutTotalLines, 29, 'সুইচ বন্ধে পাতা ২-এ লেআউট লাইন ২৯টি (মূলের ৩১টির বদলে)');
  assertEqual(offP2.explicitParaLines, 17, 'সুইচ বন্ধে পাতা ২-এ অনুচ্ছেদের সুনির্দিষ্ট লাইন ১৭টি (মূলের ২২টির বদলে)');
  assertEqual(offP2.tableRows, 9, 'সুইচ বন্ধে ir.json পাতা ২-এ ছকের সারি ৯টি (১০টির বদলে)');
});

test('২. সুইচ চালু (window.__FZ_ON_A10LINES = true) থাকলে পাতা ২-এর লাইন-সংখ্যা মূলের সমান (২৯ ও ৩১) হয়', () => {
  setSwitch(true);
  try {
    // পথ ক: সরাসরি ir.json থেকে
    const irFromFile = JSON.parse(irRaw);
    LF.fit(irFromFile, measureText);
    const xmlFromFile = Docx.bodyXml(irFromFile).xml;
    const p2SecsFile = getPageSectionsXml(xmlFromFile);
    const onP2File = analyzePage2Lines(irFromFile.pages[1], p2SecsFile[1]);

    assertEqual(onP2File.visualImageBands, imageScore.per[1].lines.truth, 'সুইচ চালুতে পাতা ২-এর দৃশ্যমান লাইন-ব্যান্ড মূলের সমান (২৯) হতে হবে');
    assertEqual(onP2File.layoutTotalLines, layoutScore.per[1].lines.orig, 'সুইচ চালুতে পাতা ২-এর লেআউট লাইন-সংখ্যা মূলের সমান (৩১) হতে হবে');
    assertEqual(onP2File.explicitParaLines, 22, 'সুইচ চালুতে পাতা ২-এর সব অনুচ্ছেদের মূল ২২টি লাইন অক্ষত থাকতে হবে');
    assertEqual(onP2File.tableRows, 10, 'সুইচ চালুতে পাতা ২-এর দুই ছকে মোট ১০টি সারি (৫ + ৫) থাকতে হবে');
    assertEqual(onP2File.trCount, 10, 'পাতা ২-এর XML-এ ঠিক ১০টি <w:tr> সারি থাকতে হবে');
    assertEqual(onP2File.brCount, 5, 'পাতা ২-এর বহু-লাইনের অনুচ্ছেদগুলোতে (২+৩+৩ লাইন) মোট ৫টি <w:br/> থাকতে হবে');

    // পথ খ: capture.json + measures.json থেকে IR.build দিয়ে
    const cap = JSON.parse(captureRaw);
    const meas = JSON.parse(measuresRaw);
    const irBuilt = IR.build(cap, meas.measures, meas.pageInfo);
    LF.fit(irBuilt, measureText);
    const xmlBuilt = Docx.bodyXml(irBuilt).xml;
    const p2SecsBuilt = getPageSectionsXml(xmlBuilt);
    const onP2Built = analyzePage2Lines(irBuilt.pages[1], p2SecsBuilt[1]);

    assertEqual(onP2Built.visualImageBands, imageScore.per[1].lines.truth, 'IR.build পথেও পাতা ২-এর দৃশ্যমান লাইন-ব্যান্ড মূলের সমান (২৯)');
    assertEqual(onP2Built.layoutTotalLines, layoutScore.per[1].lines.orig, 'IR.build পথেও পাতা ২-এর লেআউট লাইন-সংখ্যা মূলের সমান (৩১)');
    assertEqual(onP2Built.explicitParaLines, 22, 'IR.build পথেও পাতা ২-এর ২২টি অনুচ্ছেদ-লাইন অক্ষত');
    assertEqual(onP2Built.tableRows, 10, 'IR.build পথেও পাতা ২-এর দুই ছকে ১০টি সারি');
  } finally {
    setSwitch(false);
  }
});

test('৩. পাতা ২-এর ব্লক ১৫, ১৭ ও ২০-এ ফন্ট, মোটা-চিহ্ন, লাইন-দূরত্ব ও লাইন-ভাঙা নিখুঁতভাবে সংশোধিত হয়', () => {
  setSwitch(true);
  try {
    const ir = JSON.parse(irRaw);
    LF.fit(ir, measureText);
    const p2 = ir.pages[1];
    const b3 = p2.bands[3].cells[0].items[0]; // ব্লক ১৫: "বাংলাদেশ সেনাবাহিনীর..."
    const b5 = p2.bands[5].cells[0].items[0]; // ব্লক ১৭: "প্রার্থী মুক্তিযোদ্ধা..."
    const b8 = p2.bands[8].cells[0].items[0]; // ব্লক ২০: "**টীকাঃ-** যথাযথ পদ্ধতিতে..."

    assertEqual(b3.keepLines, true, 'ব্লক ১৫ (২ লাইন)-এ keepLines সক্রিয় থাকতে হবে');
    assertEqual(b3.keepJust, true, 'ব্লক ১৫-এ keepJust সক্রিয় থাকতে হবে');
    assertTrue(b3.lineSpacingPt >= 13.2 && b3.lineSpacingPt <= 15.5, 'ব্লক ১৫-এ পরিমিত লাইন-দূরত্ব থাকতে হবে');

    assertEqual(b5.bold, false, 'ব্লক ১৭-এ জোড়া-কালিজনিত ভুল bold=true দূর হতে হবে');
    assertEqual(b5.keepLines, true, 'ব্লক ১৭ (৩ লাইন)-এ keepLines সক্রিয় থাকতে হবে');
    assertEqual(b5.keepJust, true, 'ব্লক ১৭-এ keepJust সক্রিয় থাকতে হবে');

    assertEqual(b8.fontPt, 11.5, 'ব্লক ২০ ("টীকাঃ-")-এর ফন্ট ১৫pt থেকে সংশোধিত হয়ে মূল ১১.৫pt হতে হবে');
    assertEqual(b8.bold, false, 'ব্লক ২০-এ পুরো অনুচ্ছেদ bold না হয়ে শুধু **টীকাঃ-** মোটা থাকবে');
    assertEqual(b8.keepLines, true, 'ব্লক ২০ (৩ লাইন)-এ keepLines সক্রিয় থাকতে হবে');
    assertEqual(b8.keepJust, true, 'ব্লক ২০-এ keepJust সক্রিয় থাকতে হবে');
  } finally {
    setSwitch(false);
  }
});

test('৪. ক্রমিক প্রশ্নের পরের লাইনে (১০।, ১২।, ১৪।, ১৬।, ১৭।) দ্বিগুণ ট্যাব-সরণ দূর হয় এবং ১১। ও ১২।-এ লিডার-ট্যাব বসে', () => {
  setSwitch(true);
  try {
    const ir = JSON.parse(irRaw);
    LF.fit(ir, measureText);
    const p2 = ir.pages[1];
    const q10 = p2.bands[1].cells[0].items[0];
    const b7 = p2.bands[7].cells[0].items[0];
    const q14 = p2.bands[12].cells[0].items[0];

    assertEqual(q10.tabStops.length, 1, '১০। প্রশ্নে নকল ২য় ট্যাব-স্টপ থাকবে না');
    assertTrue(!q10.tabLines[1].startsWith('\t'), '১০। প্রশ্নের ২য় লাইনে বাড়তি \\t\\t থাকবে না');
    assertEqual(b7.tabLines, null, 'ব্লক ১৯ ("প্রতিবন্ধী কোটার...") contOf-এর নকল \\t\\t থেকে মুক্ত হবে');
    assertEqual(b7.indentPt, 39.3, 'ব্লক ১৯ মূলের ৩৯.৩pt বাম-ইনডেন্টে থাকবে');
    assertEqual(q14.tabStops.length, 1, '১৪। প্রশ্নে নকল ২য় ট্যাব-স্টপ থাকবে না');

    const xml = Docx.bodyXml(ir).xml;
    const p2Xml = getPageSectionsXml(xml)[1];
    assertTrue(p2Xml.includes('w:leader="hyphen"'), '১১। ও ১২। প্রশ্নের ড্যাশ পূরণ-স্থানে হাইফেন লিডার-ট্যাব থাকতে হবে');
  } finally {
    setSwitch(false);
  }
});

test('৫. পাতা ৩-এ ড্যাশ-রেখা, ছকের শিরোনাম-সারি ও শপথ-অনুচ্ছেদের প্রস্থ/অবস্থান সংশোধিত হয়', () => {
  setSwitch(true);
  try {
    const ir = JSON.parse(irRaw);
    LF.fit(ir, measureText);
    const p3 = ir.pages[2];
    const oath = p3.bands[6].cells[0].items[0]; // ব্লক ৩৩: "আমি শপথপূর্বক বলিতেছি যে..."
    assertEqual(oath.keepLines, true, 'পাতা ৩-এর শপথ অনুচ্ছেদে keepLines সক্রিয় থাকতে হবে');
    assertEqual(oath.keepJust, true, 'পাতা ৩-এর শপথ অনুচ্ছেদে keepJust সক্রিয় থাকতে হবে');
    assertTrue(oath.justRightPt >= 30 && oath.justRightPt <= 40, `শপথ অনুচ্ছেদে ডান-ইনডেন্ট ~৩৫pt হতে হবে (পাওয়া গেছে ${oath.justRightPt})`);

    const p3Xml = getPageSectionsXml(Docx.bodyXml(ir).xml)[2];
    // পাতা ৩-এর ছকের ১ম সারির উচ্চতা আগে 343 dxa (১৭.১৫pt) ছিল, এখন প্রকৃত ~265 dxa (১৩.২৫pt)
    const trHeights = [...p3Xml.matchAll(/<w:trHeight w:val="(\d+)"/g)].map((m) => Number(m[1]));
    assertTrue(trHeights.length === 3 && trHeights[0] <= 280, `পাতা ৩-এর ছকের শিরোনাম-সারির উচ্চতা ≤ ২৮০ dxa হতে হবে (পাওয়া গেছে ${trHeights[0]})`);
    // ড্যাশ বিভাজক লাইনের ট্যাব রানে ফন্ট-আকার (sz="17") বাঁধা আছে কিনা
    assertTrue(p3Xml.includes('<w:r><w:rPr><w:sz w:val="17"/><w:szCs w:val="17"/></w:rPr><w:tab/></w:r>'), 'পাতা ৩-এর ড্যাশ-রেখার ট্যাব রানে ফন্ট-আকার নির্দিষ্ট থাকতে হবে');
  } finally {
    setSwitch(false);
  }
});

test('৬. সুইচ পুনরায় বন্ধ করলে আউটপুট আবার বাইট-বাই-বাইট আগের অবস্থায় ফিরে যায়', () => {
  setSwitch(false);
  const xmlAfter = Docx.bodyXml(JSON.parse(irRaw)).xml;
  assertEqual(xmlAfter, baseXmlFromFile, 'সুইচ পুনরায় বন্ধ করলে XML বাইট-বাই-বাইট আগের মতো হতে হবে');
});

test('৭. রিবেস যাচাই: TABLECOL, PAGES4, EXTRALINES ও WRAPFIT সুইচ অক্ষত আছে এবং A10LINES-এর সাথে একত্রে কাজ করে', () => {
  assertEqual(typeof LF.isExtraLinesOn, 'function', 'line-fit.js-এ isExtraLinesOn ফাংশন থাকতে হবে');
  assertEqual(typeof LF.isWrapFitOn, 'function', 'line-fit.js-এ isWrapFitOn ফাংশন থাকতে হবে');
  assertEqual(typeof LF.isA10LinesOn, 'function', 'line-fit.js-এ isA10LinesOn ফাংশন থাকতে হবে');

  globalThis.__FZ_ON_TABLECOL = true;
  globalThis.__FZ_ON_PAGES4 = true;
  globalThis.__FZ_ON_EXTRALINES = true;
  globalThis.__FZ_ON_WRAPFIT = true;
  setSwitch(true);
  try {
    const ir = JSON.parse(irRaw);
    LF.fit(ir, measureText);
    const xml = Docx.bodyXml(ir).xml;
    const p2Secs = getPageSectionsXml(xml);
    const onP2 = analyzePage2Lines(ir.pages[1], p2Secs[1]);
    assertEqual(onP2.visualImageBands, 29, 'সব সুইচ একত্রে চালু থাকলেও পাতা ২-এর দৃশ্যমান লাইন-ব্যান্ড ২৯টি থাকতে হবে');
    assertEqual(onP2.layoutTotalLines, 31, 'সব সুইচ একত্রে চালু থাকলেও পাতা ২-এর লেআউট লাইন ৩১টি থাকতে হবে');
    assertEqual(onP2.tableRows, 10, 'সব সুইচ একত্রে চালু থাকলেও পাতা ২-এর ছকের সারি ১০টি থাকতে হবে');
  } finally {
    delete globalThis.__FZ_ON_TABLECOL;
    delete globalThis.__FZ_ON_PAGES4;
    delete globalThis.__FZ_ON_EXTRALINES;
    delete globalThis.__FZ_ON_WRAPFIT;
    setSwitch(false);
  }
});

console.log(`\nফলাফল: ${passed} পাস, ${failed} ব্যর্থ`);
if (failed > 0) process.exit(1);
